class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        import sys
        sys.setrecursionlimit(300000)
        n = len(coins)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dfs(u, p, h):
            v = coins[u] >> h
            best = v - k
            alt = v >> 1
            nh = min(h + 1, 14)
            for w in g[u]:
                if w != p:
                    best += dfs(w, u, h)
                    alt += dfs(w, u, nh)
            return max(best, alt)
        return dfs(0, -1, 0)

