class Solution {
public:
    vector<vector<int>> g;
    vector<array<long long,15>> memo;
    vector<int> coins_;
    long long K;
    long long dfs(int u, int p, int h) {
        auto &m = memo[u][h];
        if (m != LLONG_MIN) return m;
        long long v = coins_[u] >> h;
        long long best = v - K, alt = v >> 1;
        int nh = min(h + 1, 14);
        for (int w : g[u]) if (w != p) {
            best += dfs(w, u, h);
            alt += dfs(w, u, nh);
        }
        return m = max(best, alt);
    }
    long long maximumPoints(vector<vector<int>>& edges, vector<int>& coins, int k) {
        int n = coins.size();
        coins_ = coins; K = k;
        g.assign(n, {});
        for (auto &e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        memo.assign(n, {});
        for (auto &a : memo) a.fill(LLONG_MIN);
        return dfs(0, -1, 0);
    }
};

