class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        n = len(coins)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        order, par = [], [-1] * n
        stack = [0]
        while stack:
            u = stack.pop()
            order.append(u)
            for w in g[u]:
                if w != par[u]:
                    par[w] = u
                    stack.append(w)
        H = 15
        dp = [[0] * H for _ in range(n)]
        for u in reversed(order):
            for h in range(H):
                v = coins[u] >> h
                s1, s2 = v - k, v >> 1
                for w in g[u]:
                    if w != par[u]:
                        s1 += dp[w][h]
                        s2 += dp[w][min(h + 1, 14)]
                dp[u][h] = max(s1, s2)
        return dp[0][0]

